#nullable enable // autogenerated  

using MVZ2.GameContent.Effects;
using MVZ2.Vanilla.Audios;
using MVZ2.Vanilla.Entities;
using MVZ2Logic.Entities;
using MVZ2Logic.Level;
using PVZEngine.Definitions;
using PVZEngine.Entities;
using UnityEngine;

namespace MVZ2.GameContent.Projectiles
{
    [AutoEntityBehaviourDefinition(VanillaProjectileNames.Flashbang)]
    public class Flashbang : EntityBehaviourDefinition
    {
        public Flashbang(string nsp, string name) : base(nsp, name)
        {
        }
        public override void Init(Entity entity)
        {
            base.Init(entity);
            // 和 Grenade 一样：飞行途中不与任何实体碰撞，只靠落地判定触发  
            entity.CollisionMaskHostile = 0;
            entity.CollisionMaskFriendly = 0;
        }
        public override void Update(Entity projectile)
        {
            base.Update(projectile);
            if (projectile.GetRelativeY() <= 0)
            {
                Flash(projectile);
                projectile.Remove();
            }
        }
        private void Flash(Entity projectile)
        {
            var level = projectile.Level;
            var center = projectile.GetCenter();
            center.y = level.GetGroundY(center.x, center.z);

            // 落地闪光特效（沿用原闪光弹蓝图的特效）  
            level.Spawn(VanillaEffectID.stunningFlash, center, null);

            // 5×5 眩晕：格宽约 80，半径 = 2.5 格  
            float radius = 5 * 80 * 0.5f;
            bool stunned = false;
            foreach (var target in level.FindEntities(e =>
                e.IsVulnerableEntity() && projectile.IsHostile(e) && e.CanDeactive()))
            {
                if ((target.GetCenter() - center).magnitude > radius)
                    continue;
                target.Stun(150);
                stunned = true;
            }
            if (stunned)
                level.PlaySound(VanillaSoundID.stunned);
        }
    }
}
